"""Compare actual raw22/projected20 live-C0 matrices to analytic reference entries."""
from pathlib import Path
import hashlib,json
import numpy as np
from scipy.sparse import coo_matrix,load_npz
w=Path(__file__).resolve().parent;old=w.parents[1]/'full-tensor-propagator/full22-v2';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();maximum=lambda A:float(abs(A.data).max()) if A.nnz else 0.
coeff=np.array(json.loads((w/'reference-coefficients.json').read_text()));xyz=coeff[:,:3];omega=coeff[:,3];r=coeff[:,4];beta=coeff[:,6:9];grad=coeff[:,9:12];V=coeff[:,12];helper=coeff[:,13];raw=omega-1+2*np.sum(beta*grad,axis=1)/10;k2=V*raw;helper_error=float(abs(k2-helper).max());assert helper_error<1e-14
c=-10*k2/omega;n=len(c);res={'formula':'Delta P_t=Delta Theta_t=-kinput*kappa2_ref*Theta/Omega; Theta_ref=0 implies delta_kappa2*Theta_ref=0; all other reference Jacobian entries unchanged. Nonlinear finiteTheta beta couplings remain.','coefficient_schema':['x','y','z','omega','radius','alpha','betax','betay','betaz','dOmega_x','dOmega_y','dOmega_z','V','helper_k2ref'],'coefficients_sha256':sha(w/'reference-coefficients.json'),'coefficient_check_vs_helper_linf':helper_error,'core_r_le015_points':int(np.sum(r<=.15)),'transition_points':int(np.sum((r>.15)&(r<.3))),'noncore_points':int(np.sum(r>.15)),'k2ref_minmax':[float(k2.min()),float(k2.max())],'delta_entry_minmax':[float(c.min()),float(c.max())],'matrices':{}}
for kind,size,rows,theta,file in [('raw22',22,[7,17],17,'spatialnorm-cache0.0001-J22.npz'),('projected20',20,[6,15],15,'spatialnorm-projected-J20.npz')]:
 J=load_npz(w/file);J0=load_npz(old/file);row=np.ravel(np.array([size*np.arange(n)+a for a in rows]).T);col=np.repeat(size*np.arange(n)+theta,2);E=coo_matrix((np.repeat(c,2),(row,col)),shape=J.shape).tocsr();E.eliminate_zeros();delta=J-J0;err=delta-E;unexp=delta.tolil();unexp[row,col]=0.;unexp=unexp.tocsr();unexp.eliminate_zeros();core=np.ravel(size*np.where(r<=.15)[0][:,None]+np.arange(size));coreerr=maximum(delta[core,:]);record={'candidate_matrix_sha256':sha(w/file),'C0_matrix_sha256':sha(old/file),'expected_nonzero_entries':E.nnz,'actual_nonzero_entries':delta.nnz,'max_absolute_error_vs_exact':maximum(err),'max_unexpected_entry':maximum(unexp),'core_allrows_changed_entry_max':coreerr,'passed':maximum(err)<1e-8 and maximum(unexp)<1e-8 and coreerr<1e-8};assert record['passed'];res['matrices'][kind]=record
 if kind=='projected20':
  v=np.load(w.parent/'spatialnorm-validation-vectors.npz')['gauge_pulse'];res['initial_pure_gauge_action_change_l2']=float(np.linalg.norm(delta@v));res['initial_pure_gauge_action_change_linf']=float(abs(delta@v).max());assert res['initial_pure_gauge_action_change_linf']<1e-8
